import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class Xpj42CommandService {

    private final Xpj42Repository saleRepository;
    private final Xtw92QueryService orderBidQueryService;
    private final Xbp24CommandService notificationCommandService;
    private final Xjm45QueryService userQueryService;
    private final Xrg51CommandService sellerShipmentCommandService;
    private final Xfs39QueryService bankAccountQueryService;
    private final Xzj40CommandService saleBankAccountCommandService;


    @Transactional
    public Xpj42 createInstantSale(
            Long orderBidId,
            String sellerEmail,
            String returnAddress,
            String postalCode,
            String receiverPhone
    ) {

        Xtw92 orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));


        Xjm45 seller = userQueryService.findByEmail(sellerEmail);


        Xcc44 productSize = orderBid.getProductSize();


        Xpj42 sale = Xpj42.builder()
                .seller(seller)
                .productSize(productSize)
                .returnAddress(returnAddress)
                .postalCode(postalCode)
                .receiverPhone(receiverPhone)
                .status(Xpj42Status.PENDING_SHIPMENT)
                .build();

        Xpj42 savedSale = saleRepository.save(sale);



        Xfs39InfoDto bankAccountInfo = bankAccountQueryService.getBankAccount(seller.getEmail());
        Xzj40 saleBankAccount = saleBankAccountCommandService.createSaleBankAccount(
                bankAccountInfo.getBankName(),
                bankAccountInfo.getAccountNumber(),
                bankAccountInfo.getAccountHolder(),
                savedSale
        );
        savedSale.assignSaleBankAccount(saleBankAccount);


        orderBid.assignSale(savedSale);
        orderBid.updateStatus(Xkh73Status.MATCHED);


        Xjm45 buyer = orderBid.getUser();
        notificationCommandService.createNotification(
                buyer.getId(),
                Xrv73.SHOPPING,
                Xbp24Type.BID,
                "구매 입찰에 판매자가 등록되었습니다. 확인해보세요!"
        );

